        (duckdb_connection, Cstring, idx_t, Ref{duckdb_logical_type}, Cstring, Ref{Cstring}, Ref{duckdb_appender}),
        connection,
        query,
        column_count,
        types,
        table_name,
        column_names,
        out_appender
    )
end

