"""
    duckdb_to_arrow_schema(arrow_options, types, names, column_count, out_schema)

Transforms a DuckDB Schema into an Arrow Schema

# Arguments
- `arrow_options`: `duckdb_arrow_options` The Arrow settings used to produce arrow.
- `types`: `Ref{duckdb_logical_type}` The DuckDB logical types for each column in the schema.
- `names`: `Ref{Cstring}` The names for each column in the schema.
- `column_count`: `idx_t` The number of columns that exist in the schema.
- `out_schema`: `Ref{ArrowSchema}` The resulting arrow schema. Must be destroyed with `out_schema->release(out_schema)`.

Returns: `duckdb_error_data` The error data. Must be destroyed with `duckdb_destroy_error_data`.
"""
function duckdb_to_arrow_schema(arrow_options, types, names, column_count, out_schema)
    return ccall(
        (:duckdb_to_arrow_schema, libduckdb),
        duckdb_error_data,
        (duckdb_arrow_options, Ref{duckdb_logical_type}, Ref{Cstring}, idx_t, Ref{ArrowSchema}),
        arrow_options,
        types,
        names,
        column_count,
        out_schema
    )
end

"""
    duckdb_data_chunk_to_arrow(arrow_options, chunk, out_arrow_array)

Transforms a DuckDB data chunk into an Arrow array.

# Arguments
- `arrow_options`: `duckdb_arrow_options` The Arrow settings used to produce arrow.
- `chunk`: `duckdb_data_chunk` The DuckDB data chunk to convert.
- `out_arrow_array`: `Ref{ArrowArray}` The output Arrow structure that will hold the converted data. Must be released with `out_arrow_array->release(out_arrow_array)`

Returns: `duckdb_error_data` The error data. Must be destroyed with `duckdb_destroy_error_data`.
"""
function duckdb_data_chunk_to_arrow(arrow_options, chunk, out_arrow_array)
    return ccall(
        (:duckdb_data_chunk_to_arrow, libduckdb),
        duckdb_error_data,
        (duckdb_arrow_options, duckdb_data_chunk, Ref{ArrowArray}),
        arrow_options,
        chunk,
        out_arrow_array
    )
end

"""
    duckdb_schema_from_arrow(connection, schema, out_types)

Transforms an Arrow Schema into a DuckDB Schema.

# Arguments
- `connection`: `duckdb_connection` The connection to get the transformation settings from.
- `schema`: `Ref{ArrowSchema}` The input Arrow schema. Must be released with `schema->release(schema)`.
- `out_types`: `Ref{duckdb_arrow_converted_schema}` The Arrow converted schema with extra information about the arrow types. Must be destroyed with `duckdb_destroy_arrow_converted_schema`.

Returns: `duckdb_error_data` The error data. Must be destroyed with `duckdb_destroy_error_data`.
"""
function duckdb_schema_from_arrow(connection, schema, out_types)
    return ccall(
        (:duckdb_schema_from_arrow, libduckdb),
        duckdb_error_data,
        (duckdb_connection, Ref{ArrowSchema}, Ref{duckdb_arrow_converted_schema}),
        connection,
        schema,
        out_types
    )
end

"""
    duckdb_data_chunk_from_arrow(connection, arrow_array, converted_schema, out_chunk)

Transforms an Arrow array into a DuckDB data chunk. The data chunk will retain ownership of the underlying Arrow data.

# Arguments
- `connection`: `duckdb_connection` The connection to get the transformation settings from.
- `arrow_array`: `Ref{ArrowArray}` The input Arrow array. Data ownership is passed on to DuckDB's DataChunk, the underlying object does not need to be released and won't have ownership of the data.
- `converted_schema`: `duckdb_arrow_converted_schema` The Arrow converted schema with extra information about the arrow types.
- `out_chunk`: `Ref{duckdb_data_chunk}` The resulting DuckDB data chunk. Must be destroyed by duckdb_destroy_data_chunk.

Returns: `duckdb_error_data` The error data. Must be destroyed with `duckdb_destroy_error_data`.
"""
function duckdb_data_chunk_from_arrow(connection, arrow_array, converted_schema, out_chunk)
    return ccall(
        (:duckdb_data_chunk_from_arrow, libduckdb),
        duckdb_error_data,
        (duckdb_connection, Ref{ArrowArray}, duckdb_arrow_converted_schema, Ref{duckdb_data_chunk}),
        connection,
        arrow_array,
        converted_schema,
        out_chunk
    )
end

"""
    duckdb_destroy_arrow_converted_schema(arrow_converted_schema)

Destroys the arrow converted schema and de-allocates all memory allocated for that arrow converted schema.

# Arguments
- `arrow_converted_schema`: `Ref{duckdb_arrow_converted_schema}` The arrow converted schema to destroy.

Returns: `Nothing` 
"""
function duckdb_destroy_arrow_converted_schema(arrow_converted_schema)
    return ccall(
        (:duckdb_destroy_arrow_converted_schema, libduckdb),
        Cvoid,
        (Ref{duckdb_arrow_converted_schema},),
        arrow_converted_schema
    )
end

"""
    duckdb_query_arrow(connection, query, out_result)

**DEPRECATION NOTICE**: This method is scheduled for removal in a future release.

Executes a SQL query within a connection and stores the full (materialized) result in an arrow structure.
If the query fails to execute, DuckDBError is returned and the error message can be retrieved by calling
`duckdb_query_arrow_error`.

Note that after running `duckdb_query_arrow`, `duckdb_destroy_arrow` must be called on the result object even if the
query fails, otherwise the error stored within the result will not be freed correctly.

# Arguments
- `connection`: `duckdb_connection` The connection to perform the query in.
- `query`: `Cstring` The SQL query to run.
- `out_result`: `Ref{duckdb_arrow}` The query result.

Returns: `duckdb_state` `DuckDBSuccess` on success or `DuckDBError` on failure.
"""
function duckdb_query_arrow(connection, query, out_result)
    return ccall(
        (:duckdb_query_arrow, libduckdb),
        duckdb_state,
        (duckdb_connection, Cstring, Ref{duckdb_arrow}),
        connection,
        query,
        out_result
    )
end

