"""
    duckdb_client_context_get_catalog(context, catalog_name)

Retrieve a database catalog instance by name.
This function can only be called from within the context of an active transaction, e.g. during execution of a registered function callback. Otherwise returns `nullptr`.

# Arguments
- `context`: `duckdb_client_context` The client context.
- `catalog_name`: `Cstring` The name of the catalog.

Returns: `duckdb_catalog` The resulting catalog instance, or `nullptr` if called from outside an active transaction or if a catalog with the specified name does not exist. Must be destroyed with `duckdb_destroy_catalog`
"""
function duckdb_client_context_get_catalog(context, catalog_name)
    return ccall(
        (:duckdb_client_context_get_catalog, libduckdb),
        duckdb_catalog,
        (duckdb_client_context, Cstring),
        context,
        catalog_name
    )
end

"""
    duckdb_catalog_get_type_name(catalog)

Retrieve the \"type name\" of the given catalog.
E.g. for a DuckDB database, this returns 'duckdb'.
The returned string is owned by the catalog and remains valid until the catalog is destroyed.

# Arguments
- `catalog`: `duckdb_catalog` The catalog.

Returns: `Cstring` The type name of the catalog.
"""
function duckdb_catalog_get_type_name(catalog)
    return ccall((:duckdb_catalog_get_type_name, libduckdb), Cstring, (duckdb_catalog,), catalog)
end

"""
    duckdb_catalog_get_entry(catalog, context, entry_type, schema_name, entry_name)

Retrieve a catalog entry from the given catalog by type, schema name and entry name.
The returned catalog entry remains valid for the duration of the current transaction.

# Arguments
- `catalog`: `duckdb_catalog` The catalog.
- `context`: `duckdb_client_context` The client context.
- `entry_type`: `duckdb_catalog_entry_type` The type of the catalog entry to retrieve.
- `schema_name`: `Cstring` The schema name of the catalog entry.
- `entry_name`: `Cstring` The name of the catalog entry.

Returns: `duckdb_catalog_entry` The resulting catalog entry, or `nullptr` if no such entry exists. Must be destroyed with `duckdb_destroy_catalog_entry`. Remains valid for the duration of the current transaction.
"""
function duckdb_catalog_get_entry(catalog, context, entry_type, schema_name, entry_name)
    return ccall(
        (:duckdb_catalog_get_entry, libduckdb),
        duckdb_catalog_entry,
        (duckdb_catalog, duckdb_client_context, duckdb_catalog_entry_type, Cstring, Cstring),
        catalog,
        context,
        entry_type,
        schema_name,
        entry_name
    )
end

"""
    duckdb_destroy_catalog(catalog)

Destroys the given catalog instance.

Note that this does not actually \"drop\" the contents of the catalog; it merely frees the C API handle.

# Arguments
- `catalog`: `Ref{duckdb_catalog}` The catalog instance to destroy.

Returns: `Nothing` 
"""
function duckdb_destroy_catalog(catalog)
    return ccall((:duckdb_destroy_catalog, libduckdb), Cvoid, (Ref{duckdb_catalog},), catalog)
end

