    return ccall((:duckdb_catalog_entry_get_type, libduckdb), duckdb_catalog_entry_type, (duckdb_catalog_entry,), entry)
end

"""
    duckdb_catalog_entry_get_name(entry)

Get the name of the given catalog entry.

# Arguments
- `entry`: `duckdb_catalog_entry` The catalog entry.

