- `vector`: `duckdb_vector` The vector to slice.
- `sel`: `duckdb_selection_vector` The selection vector.
- `len`: `idx_t` The length of the selection vector.

Returns: `Nothing` 
"""
function duckdb_slice_vector(vector, sel, len)
    return ccall(
        (:duckdb_slice_vector, libduckdb),
        Cvoid,
        (duckdb_vector, duckdb_selection_vector, idx_t),
        vector,
        sel,
        len
    )
end

"""
    duckdb_vector_copy_sel(src, dst, sel, src_count, src_offset, dst_offset)

Copy the src vector to the dst with a selection vector that identifies which indices to copy.

# Arguments
- `src`: `duckdb_vector` The vector to copy from.
- `dst`: `duckdb_vector` The vector to copy to.
- `sel`: `duckdb_selection_vector` The selection vector. The length of the selection vector should not be more than the length of the src vector
- `src_count`: `idx_t` The number of entries from selection vector to copy. Think of this as the effective length of the selection vector starting from index 0
- `src_offset`: `idx_t` The offset in the selection vector to copy from (important: actual number of items copied = src_count - src_offset).
- `dst_offset`: `idx_t` The offset in the dst vector to start copying to.

Returns: `Nothing` 
"""
function duckdb_vector_copy_sel(src, dst, sel, src_count, src_offset, dst_offset)
    return ccall(
        (:duckdb_vector_copy_sel, libduckdb),
        Cvoid,
        (duckdb_vector, duckdb_vector, duckdb_selection_vector, idx_t, idx_t, idx_t),
        src,
        dst,
        sel,
        src_count,
        src_offset,
        dst_offset
    )
end

